g.title:
MATCH (n)
WHERE n.links IS NOT NULL
// Q756=plantae Q1390=insecta Q5113=birb Q7377=mammal Q127282=actinopter Q1360=arthopoda Q729=animal
//AND EXISTS { ({qid: 'Q729'})-[:HAS_CHILD*]->(n) } 
AND NOT EXISTS { (p)-[:HAS_CHILD*]->(n) WHERE p.qid IN ['Q756','Q1390','Q5113','Q7377','Q127282']  } 
WITH n
ORDER BY n.links DESC
LIMIT 120
MATCH path = ()-[:HAS_CHILD*]->(n)
RETURN DISTINCT path
